mapper.select:
SELECT p.*, c.name as category_name FROM product p LEFT JOIN category c ON p.category_id = c.id WHERE 1=1
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.create_time DESC
